use std::io::Write;

struct Trickle(Vec<u8>);

impl Write for Trickle {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        let n = buf.len().min(3);
        self.0.extend_from_slice(&buf[..n]);
        Ok(n)
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

fn main() {
    let mut a = Trickle(Vec::new());
    let n = a.write(b"Hello, world").expect("ok");
    let mut b = Trickle(Vec::new());
    b.write_all(b"Hello, world").expect("ok");
    println!("write: {n} bytes, write_all: {} bytes", b.0.len());
}

use std::io::{BufRead, BufReader, Read, Write};
use std::net::{Shutdown, TcpListener, TcpStream};
use std::thread;

fn main() -> std::io::Result<()> {
    let listener = TcpListener::bind("127.0.0.1:0")?;
    let port = listener.local_addr()?.port();
    let client = thread::spawn(move || -> std::io::Result<String> {
        let mut s = TcpStream::connect(("127.0.0.1", port))?;
        s.write_all(b"GET / HTTP/1.1\r\n\r\n")?;
        s.shutdown(Shutdown::Write)?;
        let mut reply = String::new();
        s.read_to_string(&mut reply)?;
        Ok(reply)
    });
    let (mut stream, _) = listener.accept()?;
    let mut line = String::new();
    BufReader::new(&mut stream).read_line(&mut line)?;
    let body = format!("you asked for: {}", line.trim_end());
    let reply = format!("HTTP/1.1 200 OK\r\nContent-Length: {}\r\n\r\n{body}", body.len());
    stream.write_all(reply.as_bytes())?;
    drop(stream);
    let got = client.join().expect("no panic")?;
    println!("{}", got.lines().last().unwrap_or(""));
    Ok(())
}

