use std::sync::{Arc, Mutex, mpsc};
use std::thread;

type Job = Box<dyn FnOnce() + Send + 'static>;

fn main() {
    let (sender, receiver) = mpsc::channel::<Job>();
    let receiver = Arc::new(Mutex::new(receiver));
    let workers: Vec<_> = (0..2)
        .map(|id| {
            let receiver = Arc::clone(&receiver);
            thread::spawn(move || {
                let mut done = 0;
                loop {
                    let message = receiver.lock().expect("not poisoned").recv();
                    match message {
                        Ok(job) => {
                            job();
                            done += 1;
                        }
                        Err(_) => break,
                    }
                }
                (id, done)
            })
        })
        .collect();
    for _ in 0..6 {
        sender.send(Box::new(|| {})).expect("sent");
    }
    drop(sender);
    let total: usize = workers.into_iter().map(|w| w.join().expect("no panic").1).sum();
    println!("{total} jobs done");
}

use std::sync::{Arc, Mutex, mpsc};
use std::thread;
use std::time::{Duration, Instant};

fn main() {
    let (tx, rx) = mpsc::channel::<u64>();
    let rx = Arc::new(Mutex::new(rx));
    let start = Instant::now();
    let workers: Vec<_> = (0..2)
        .map(|_| {
            let rx = Arc::clone(&rx);
            thread::spawn(move || {
                let job = rx.lock().expect("ok").recv();
                if let Ok(ms) = job {
                    thread::sleep(Duration::from_millis(ms));
                }
            })
        })
        .collect();
    tx.send(300).expect("sent");
    tx.send(300).expect("sent");
    for w in workers {
        w.join().expect("no panic");
    }
    println!("ran in parallel: {}", start.elapsed() < Duration::from_millis(550));
}

