use std::thread;

struct Worker {
    id: usize,
    thread: Option<thread::JoinHandle<()>>,
}

struct Pool {
    workers: Vec<Worker>,
}

impl Drop for Pool {
    fn drop(&mut self) {
        for worker in &mut self.workers {
            if let Some(thread) = worker.thread.take() {
                thread.join().expect("no panic");
                println!("joined worker {}", worker.id);
            }
        }
    }
}

fn main() {
    let _pool = Pool {
        workers: (0..2)
            .map(|id| Worker {
                id,
                thread: Some(thread::spawn(|| {})),
            })
            .collect(),
    };
}

use std::sync::{Arc, Mutex, mpsc};
use std::thread;

fn main() {
    let (sender, receiver) = mpsc::channel::<u32>();
    let receiver = Arc::new(Mutex::new(receiver));
    let rx = Arc::clone(&receiver);
    let worker = thread::spawn(move || {
        let mut seen = 0;
        loop {
            let message = rx.lock().expect("ok").recv();
            match message {
                Ok(_) => seen += 1,
                Err(_) => break,
            }
        }
        seen
    });
    for n in 0..3 {
        sender.send(n).expect("sent");
    }
    drop(sender);
    println!("worker saw {} jobs and stopped", worker.join().expect("no panic"));
}

fn main() {
    let steps = ["drop the sender", "workers finish queued jobs", "recv fails, loops end", "join each worker"];
    for (i, step) in steps.iter().enumerate() {
        println!("{}. {step}", i + 1);
    }
}

