            id,
            thread: Some(thread),
        }
    }
}

impl ThreadPool {
    pub fn shutdown(mut self) -> Vec<usize> {
        self.stop()
    }

    fn stop(&mut self) -> Vec<usize> {
        drop(self.sender.take());
